1: #requires -Version 7
2: <#
3:   score.ps1 — 主控测试评分器（4 维 + 混淆矩阵）
4:   用法: pwsh score.ps1 -Suite screen|full
5:   输出: results\score-<suite>.json + 控制台表格
6:   口径（与 tasks-master.json _meta.scoring 一致）:
7:     tool_selection 0.35 / completeness 0.25 / routing 0.25 / efficiency 0.15
8:     format_error → 全维 0
9: #>
10: param(
11:   [ValidateSet('screen','full')]
12:   [string]$Suite = 'screen',
13:   [double]$WTool = 0.35, [double]$WComp = 0.25, [double]$WRoute = 0.25, [double]$WEff = 0.15
14: )
15: $ErrorActionPreference = 'Stop'
16: $dir = Split-Path -Parent $MyInvocation.MyCommand.Path
17: $resDir = Join-Path $dir 'results'
18: $doc = Get-Content (Join-Path $dir 'tasks-master.json') -Raw -Encoding UTF8 | ConvertFrom-Json
19: $taskMap = @{}; foreach ($t in $doc.tasks) { $taskMap[$t.id] = $t }
20: $rows = (Get-Content (Join-Path $resDir "bench-$Suite.json") -Raw -Encoding UTF8 | ConvertFrom-Json).rows
21: 
22: $out = @()
23: foreach ($r in $rows) {
24:   if ($r.error) { $out += [pscustomobject]@{ model=$r.model; task=$r.task; error=$r.error; total=0 }; continue }
25:   if ($r.task -eq 'ping') { continue }
26:   $t = $taskMap[$r.task]
27:   $parsed = $null
28:   try { $parsed = $r.raw | ConvertFrom-Json } catch { }
29:   if (-not $parsed -or -not $parsed.route) {
30:     $out += [pscustomobject]@{ model=$r.model; task=$r.task; format_error=$true; tool=0; comp=0; route=0; eff=0; total=0 }
31:     continue
32:   }
33:   $routeScore = if ($parsed.route -eq $t.route_expect) { 1.0 } else { 0.0 }
34:   $steps = @($parsed.steps) | Where-Object { $_ -and $_.tool }
35:   # tool_selection
36:   $toolScore = 0.0
37:   if ($t.route_expect -ne 'execute_tools') {
38:     $toolScore = if ($steps.Count -eq 0) { 1.0 } else { 0.0 }
39:   } elseif ($steps.Count -gt 0) {
40:     $sum = 0.0
41:     foreach ($s in $steps) {
42:       if ($t.optimal_tools -contains $s.tool) { $sum += 1.0 }
43:       elseif ($t.acceptable_tools -contains $s.tool) { $sum += 0.6 }
44:     }
45:     $toolScore = $sum / [Math]::Max(1, $steps.Count)
46:   }
47:   # completeness: required 关键词（支持 a|b 交替）在 analysis+intent+notes 中 recall
48:   $text = (@($parsed.analysis) + @($steps | ForEach-Object { $_.intent }) + @($parsed.notes)) -join ' '
49:   $hit = 0; $req = @($t.required).Count
50:   foreach ($pat in $t.required) { if ($text -match $pat) { $hit++ } }
51:   $compScore = if ($req -gt 0) { $hit / $req } else { 1.0 }
52:   # efficiency
53:   $effScore = if ($t.route_expect -ne 'execute_tools') { 1.0 }
54:     elseif ($steps.Count -ge 1) { [Math]::Min(1.0, $t.optimal_steps / $steps.Count) } else { 0.0 }
55:   $total = [math]::Round($WTool*$toolScore + $WComp*$compScore + $WRoute*$routeScore + $WEff*$effScore, 3)
56:   $out += [pscustomobject]@{ model=$r.model; task=$r.task; route_got=$parsed.route; route_expect=$t.route_expect
57:     n_steps=$steps.Count; tool=[math]::Round($toolScore,2); comp=[math]::Round($compScore,2)
58:     routeS=$routeScore; eff=[math]::Round($effScore,2); total=$total; ms=$r.ms }
59: }
